-- EDUNEXUS curated knowledge registry + curriculum v2.
-- Original lesson summaries/exercises; references link to authoritative sources.
-- Idempotent seed. Review licenses before copying third-party material.
BEGIN;

CREATE TABLE IF NOT EXISTS public.knowledge_sources (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  source_key text NOT NULL UNIQUE,
  title text NOT NULL,
  url text NOT NULL UNIQUE,
  publisher text NOT NULL,
  trust_tier text NOT NULL CHECK (trust_tier IN ('A','B','C')),
  license_note text NOT NULL,
  summary text NOT NULL,
  reviewed_at date NOT NULL DEFAULT CURRENT_DATE,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.knowledge_sources ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS knowledge_sources_public_read ON public.knowledge_sources;
CREATE POLICY knowledge_sources_public_read ON public.knowledge_sources
  FOR SELECT TO PUBLIC USING (true);
GRANT SELECT ON public.knowledge_sources TO PUBLIC;

INSERT INTO public.knowledge_sources
(source_key,title,url,publisher,trust_tier,license_note,summary,reviewed_at)
VALUES
('CURRICULUM-ID-KEMENDIKDASMEN','Panduan Mata Pelajaran dan Capaian Pembelajaran Indonesia','https://kurikulum.kemendikdasmen.go.id/panduan-mapel','Kementerian Pendidikan Dasar dan Menengah RI','A','Simpan metadata dan tautan; cek izin sebelum menyalin dokumen.','Panduan resmi untuk menerjemahkan Capaian Pembelajaran ke praktik pembelajaran dan perencanaan kelas.',DATE '2026-10-14'),
('CURRICULUM-ID-PUSKUR','Pusat Kurikulum dan Pembelajaran: Panduan Asesmen dan Pembelajaran','https://puskur.kemendikdasmen.go.id/','Pusat Kurikulum dan Pembelajaran','A','Simpan metadata dan tautan; cek lisensi setiap dokumen.','Panduan perencanaan pembelajaran, asesmen formatif/sumatif, ATP, dan pelaporan hasil belajar.',DATE '2026-10-14'),
('UNESCO-AI-STUDENT','UNESCO AI Competency Framework for Students','https://www.unesco.org/en/articles/ai-competency-framework-students','UNESCO','A','Ringkasan dan tautan; atribusi; cek lisensi publikasi sebelum adaptasi.','Kerangka kompetensi AI siswa: human-centred mindset, etika, teknik/aplikasi, desain sistem; understand/apply/create.',DATE '2026-10-14'),
('UNESCO-AI-TEACHER','UNESCO AI Competency Framework for Teachers','https://www.unesco.org/en/articles/ai-competency-framework-teachers','UNESCO','A','Ringkasan dan tautan; atribusi; cek lisensi publikasi sebelum adaptasi.','Kompetensi AI pendidik, termasuk etika, pedagogi AI, aplikasi dan pengembangan profesional.',DATE '2026-10-14'),
('UNESCO-GENAI-EDUCATION','Guidance for Generative AI in Education and Research','https://www.unesco.org/en/articles/guidance-generative-ai-education-and-research','UNESCO','A','Ringkasan dan tautan; perlindungan privasi dan ketentuan publikasi berlaku.','Panduan penggunaan GenAI berpusat pada manusia, privasi, kesiapan pedagogis dan tata kelola.',DATE '2026-10-14'),
('OECD-LEARNING-COMPASS','OECD Learning Compass 2030','https://www.oecd.org/en/data/tools/oecd-learning-compass-2030.html','OECD','A','Gunakan ringkasan dan tautan; periksa ketentuan penggunaan OECD.','Kerangka aspiratif yang menekankan agency pembelajar, well-being, pengetahuan, keterampilan, sikap dan nilai.',DATE '2026-10-14'),
('ONET-SKILLS','O*NET Database — Skills, Knowledge and Occupations','https://www.onetcenter.org/database.html','U.S. Department of Labor, Employment and Training Administration','A','Database CC BY 4.0 kecuali dinyatakan lain; atribusi dan catat perubahan; validasi konteks Indonesia.','Dataset keterampilan, pengetahuan, tugas, aktivitas dan pekerjaan dengan unduhan/API.',DATE '2026-10-14'),
('ESCO-API','ESCO Skills, Competences, Qualifications and Occupations API','https://esco.ec.europa.eu/en/use-esco/use-esco-services-api/esco-web-service-api','European Commission','A','Simpan versi API/dataset dan ikuti lisensi ESCO yang berlaku.','Klasifikasi multibahasa untuk menghubungkan keterampilan, kompetensi, kualifikasi dan pekerjaan.',DATE '2026-10-14'),
('UNESCO-DIGITAL-LITERACY','UNESCO Digital Literacy Global Framework','https://www.uis.unesco.org/en/gaml/monitoring-framework','UNESCO Institute for Statistics','A','Ringkasan dan tautan; periksa lisensi publikasi sebelum reproduksi.','Kerangka referensi untuk pengukuran kecakapan literasi digital.',DATE '2026-10-14'),
('WCAG-22','Web Content Accessibility Guidelines (WCAG) 2.2','https://www.w3.org/TR/WCAG22/','W3C','A','Rekomendasi W3C; tautkan spesifikasi dan hormati ketentuan dokumen.','Rekomendasi aksesibilitas web termasuk keyboard, fokus, label, kontras dan konten alternatif.',DATE '2026-10-14'),
('MIT-OCW','MIT OpenCourseWare','https://ocw.mit.edu/get-started/','MIT OpenCourseWare','B','CC BY-NC-SA; nonkomersial, atribusi, share-alike. Jangan reuse dalam produk komersial tanpa izin.','Materi kursus, silabus, bacaan, tugas dan ujian sebagai rujukan pembelajaran terbuka.',DATE '2026-10-14'),
('OPENSTAX-LICENSE','OpenStax textbook licensing','https://help.openstax.org/s/article/Openstax-textbook-licensing-and-customization','OpenStax','B','CC BY-NC-SA; bukan untuk penggunaan komersial tanpa izin.','Ketentuan lisensi buku terbuka OpenStax; gunakan metadata dan tautan sampai hak komersial dikonfirmasi.',DATE '2026-10-14'),
('OWASP-LLM-TOP10','OWASP Top 10 for Large Language Model Applications','https://owasp.org/www-project-top-10-for-large-language-model-applications/','OWASP','A','Ringkasan keamanan dan tautan ke proyek OWASP.','Risiko LLM termasuk prompt injection, kebocoran data, output tidak aman dan tool use yang berlebihan.',DATE '2026-10-14'),
('OER-LICENSE-PRACTICE','Creative Commons licenses','https://creativecommons.org/share-your-work/cclicenses/','Creative Commons','A','Ikuti syarat spesifik lisensi, termasuk atribusi, nonkomersial dan share-alike.','Referensi untuk menilai izin penggunaan, adaptasi dan redistribusi materi pendidikan.',DATE '2026-10-14')
ON CONFLICT (source_key) DO UPDATE SET
 title=EXCLUDED.title,url=EXCLUDED.url,publisher=EXCLUDED.publisher,trust_tier=EXCLUDED.trust_tier,
 license_note=EXCLUDED.license_note,summary=EXCLUDED.summary,reviewed_at=EXCLUDED.reviewed_at,updated_at=now();

