('Literasi Digital, Informasi dan Keamanan Siber','literasi-digital-keamanan','Menilai informasi digital, melindungi akun dan data, serta mengenali risiko daring.'),
('Literasi Data dan Berpikir Kritis','literasi-data-berpikir-kritis','Mengajukan pertanyaan yang dapat diuji, membaca data dan mengomunikasikan kesimpulan dengan batasan.'),
('Pembelajaran Mandiri dan Metakognisi','pembelajaran-mandiri-metakognisi','Menyusun tujuan belajar, latihan pengambilan kembali, refleksi dan strategi perbaikan.'),
('Keterampilan Kerja, Komunikasi dan Karier','keterampilan-kerja-komunikasi-karier','Mengembangkan komunikasi profesional, kolaborasi, pemecahan masalah dan rencana pengembangan karier.')
) AS v(name,slug,description)
WHERE p.slug='literasi-digital-ai-kesiapan-masa-depan'
ON CONFLICT (slug) DO UPDATE SET program_id=EXCLUDED.program_id,name=EXCLUDED.name,description=EXCLUDED.description,updated_at=now();

