('literasi-digital-keamanan','Memverifikasi Informasi Digital',1),
('literasi-digital-keamanan','Privasi, Akun dan Keamanan',2),
('literasi-data-berpikir-kritis','Pertanyaan, Data dan Kualitas Bukti',1),
('literasi-data-berpikir-kritis','Interpretasi dan Komunikasi Temuan',2),
('pembelajaran-mandiri-metakognisi','Tujuan dan Strategi Belajar',1),
('pembelajaran-mandiri-metakognisi','Latihan, Umpan Balik dan Refleksi',2),
('keterampilan-kerja-komunikasi-karier','Komunikasi dan Kolaborasi',1),
('keterampilan-kerja-komunikasi-karier','Pemecahan Masalah dan Rencana Karier',2)
) AS v(course_slug,name,position) ON c.slug=v.course_slug
