INSERT INTO public.lessons(module_id,title,content,position)
SELECT m.id,v.title,jsonb_build_object('summary',v.summary,'objectives',jsonb_build_array(v.objective),
'sections',jsonb_build_array(jsonb_build_object('heading','Materi inti','body',v.body),
jsonb_build_object('heading','Periksa pemahaman','body',v.check_question)),
'exercise',v.exercise,'source_ids',v.source_ids),v.lesson_position
FROM (VALUES
('literasi-ai-etika',1,1,'Apa yang Dapat dan Tidak Dapat Dilakukan AI','AI generatif menghasilkan keluaran berdasarkan pola dari data dan instruksi, tetapi keluaran dapat keliru atau tidak lengkap.','Membedakan kemampuan, keterbatasan dan jenis kesalahan AI.','AI dapat membantu membuat draf, menjelaskan konsep dan menghasilkan ide. Namun, AI dapat mengarang fakta atau referensi, gagal memahami konteks, dan mewarisi bias. Perlakukan hasil sebagai usulan yang perlu diperiksa, bukan sebagai bukti otomatis.','Apakah keluaran AI selalu benar? Jelaskan satu risiko dan satu cara memeriksanya.','Buat tabel tiga kolom: tugas yang cocok dibantu AI, risiko, dan verifikasi manusia.','UNESCO-AI-STUDENT,UNESCO-GENAI-EDUCATION'),
('literasi-ai-etika',1,2,'Menyusun Prompt dan Memeriksa Jawaban','Instruksi yang jelas memuat konteks, tujuan, format keluaran dan kriteria mutu.','Membuat prompt yang terarah dan mengevaluasi keluaran menggunakan kriteria eksplisit.','Berikan konteks yang tidak sensitif, jelaskan tugas, audiens, batasan, dan bentuk jawaban. Minta AI menyatakan asumsi dan ketidakpastian. Periksa klaim penting menggunakan sumber primer, tanggal, dan perhitungan mandiri.','Bagaimana Anda akan memverifikasi sebuah kutipan atau statistik yang diberikan AI?','Buat prompt untuk menjelaskan suatu konsep, lalu buat daftar tiga pemeriksaan fakta sebelum menggunakan jawabannya.','UNESCO-AI-STUDENT,OWASP-LLM-TOP10'),
('literasi-ai-etika',2,1,'Privasi, Bias dan Pengawasan Manusia','Penggunaan AI perlu mempertimbangkan data pribadi, bias, konteks dan tanggung jawab keputusan.','Mengenali informasi sensitif dan memilih tindakan yang melindungi privasi.','Jangan memasukkan data pribadi, kredensial, data kesehatan atau dokumen rahasia ke layanan yang belum disetujui. Evaluasi apakah contoh dan rekomendasi merugikan kelompok tertentu. Untuk keputusan berdampak tinggi, pertahankan peninjauan manusia dan jalur keberatan.','Data apa yang sebaiknya tidak dimasukkan ke chatbot publik?','Tinjau contoh prompt berisi identitas siswa; tulis ulang dengan data yang diminimalkan dan dianonimkan.','UNESCO-GENAI-EDUCATION,UNESCO-AI-TEACHER'),
('literasi-ai-etika',2,2,'Menggunakan AI untuk Belajar, Bukan Menyalin','AI paling berguna ketika memperkuat pemahaman, latihan dan umpan balik tanpa menggantikan proses berpikir pembelajar.','Merancang penggunaan AI yang memperlihatkan proses belajar dan kontribusi sendiri.','Minta AI memberi petunjuk bertahap, pertanyaan Socratic, contoh pembanding atau umpan balik atas draf sendiri. Ikuti aturan institusi mengenai pengungkapan penggunaan AI dan jangan menyerahkan keluaran AI sebagai karya mandiri jika dilarang.','Bagaimana Anda membedakan bantuan belajar dari plagiarisme atau pelanggaran aturan?','Buat rencana belajar 20 menit dengan AI sebagai tutor yang memberi petunjuk, lalu jawab latihan tanpa bantuan.','UNESCO-AI-STUDENT,UNESCO-GENAI-EDUCATION'),
('literasi-digital-keamanan',1,1,'Memeriksa Kredibilitas Sumber','Kredibilitas informasi dinilai melalui asal sumber, bukti, tanggal, metode dan konfirmasi independen.','Memeriksa penulis, penerbit, tanggal, bukti dan konteks klaim digital.','Buka sumber asli, baca bagian yang mendukung klaim, periksa tanggal, cari data atau dokumen primer, dan bandingkan dengan sumber independen. Hasil pencarian populer tidak otomatis benar; gambar dan kutipan dapat dilepas dari konteks.','Apa perbedaan antara sumber primer dan unggahan yang hanya mengulang klaim?','Pilih satu klaim publik, telusuri sumber aslinya, lalu catat bukti pendukung dan informasi yang masih belum diketahui.','UNESCO-DIGITAL-LITERACY,CURRICULUM-ID-PUSKUR'),
('literasi-digital-keamanan',1,2,'Misinformasi, Manipulasi dan Konteks','Konten yang meyakinkan dapat salah, dipotong, dibuat sintetis atau disebarkan tanpa konteks.','Menggunakan langkah pemeriksaan sebelum membagikan informasi.','Periksa tanggal dan lokasi, lakukan pencarian silang, telusuri foto ke sumber awal bila memungkinkan, dan bedakan bukti dari opini. Jangan menyimpulkan autentisitas hanya dari kualitas visual atau jumlah interaksi.','Pemeriksaan apa yang perlu dilakukan sebelum membagikan berita mengejutkan?','Susun checklist lima langkah untuk memeriksa gambar atau berita yang viral.','UNESCO-DIGITAL-LITERACY'),
('literasi-digital-keamanan',2,1,'Kata Sandi, MFA dan Pemulihan Akun','Keamanan akun bergantung pada kata sandi unik, autentikasi tambahan dan jalur pemulihan yang aman.','Memilih praktik autentikasi yang mengurangi risiko pengambilalihan akun.','Gunakan kata sandi panjang dan unik, pengelola kata sandi bila tersedia, MFA atau passkey, serta kode pemulihan yang disimpan aman. Jangan berbagi OTP. Periksa domain sebelum login dan akses akun dari tautan resmi.','Mengapa kata sandi yang sama untuk banyak layanan meningkatkan risiko?','Audit akun simulasi dan buat rencana perbaikan: kata sandi, MFA, pemulihan dan sesi aktif.','UNESCO-DIGITAL-LITERACY,OWASP-LLM-TOP10'),
('literasi-digital-keamanan',2,2,'Privasi, Jejak Digital dan Phishing','Informasi yang dibagikan dapat disalin atau digunakan di luar konteks; phishing sering memanfaatkan urgensi dan penyamaran.','Mengenali indikator phishing dan mengurangi paparan data pribadi.','Periksa alamat pengirim dan domain, jangan membuka lampiran tak terduga, jangan membagikan kode rahasia, dan konfirmasi permintaan mendesak melalui saluran kedua. Bagikan hanya data yang diperlukan dan pahami pengaturan privasi layanan.','Apa tindakan aman saat menerima permintaan transfer atau OTP yang mendesak?','Tandai indikator risiko pada email phishing simulasi dan tulis respons pelaporan yang aman.','UNESCO-GENAI-EDUCATION,OWASP-LLM-TOP10'),
('literasi-data-berpikir-kritis',1,1,'Menyusun Pertanyaan yang Dapat Diuji','Analisis data dimulai dengan pertanyaan yang jelas, metrik, periode, unit analisis dan keputusan yang ingin didukung.','Mengubah keluhan umum menjadi pertanyaan yang dapat diperiksa dengan bukti.','Tentukan keputusan yang perlu dibuat, variabel yang diamati, periode, kelompok pembanding dan sumber data. Nyatakan informasi yang belum tersedia. Hindari memilih metrik hanya karena mudah diukur.','Apa yang membuat pertanyaan “kinerja turun” belum cukup spesifik?','Ubah klaim “pelanggan tidak puas” menjadi pertanyaan dengan metrik, populasi, dan periode yang jelas.','ONET-SKILLS,OECD-LEARNING-COMPASS'),
('literasi-data-berpikir-kritis',1,2,'Kualitas Data dan Ketidakpastian','Kesimpulan bergantung pada kualitas sampel, definisi, data hilang dan metode pengukuran.','Memeriksa keterbatasan data sebelum menarik kesimpulan.','Periksa asal data, ukuran sampel, cara pengumpulan, definisi kategori, data hilang, potensi bias dan rentang waktu. Korelasi tidak membuktikan sebab-akibat. Nyatakan ketidakpastian dan hindari presisi palsu.','Apa yang tidak dapat disimpulkan dari dua variabel yang bergerak bersamaan?','Buat daftar pemeriksaan kualitas untuk sebuah tabel survei kecil.','ONET-SKILLS,UNESCO-DIGITAL-LITERACY'),
('literasi-data-berpikir-kritis',2,1,'Membaca Tren dan Perbandingan','Perbandingan memerlukan satuan, denominator, periode dan definisi metrik yang konsisten.','Membedakan perubahan absolut, perubahan relatif dan perubahan yang tidak sebanding.','Periksa label sumbu, satuan, rentang waktu, denominator dan perubahan definisi. Laporkan jumlah awal bersama persentase jika basis kecil. Grafik dapat menyesatkan jika skala dipotong atau kategori dihilangkan.','Kapan kenaikan 50 persen dapat berarti perubahan jumlah yang kecil?','Tulis interpretasi dua periode data dan sebutkan minimal dua batasan sebelum memberi rekomendasi.','ONET-SKILLS,OECD-LEARNING-COMPASS'),
('literasi-data-berpikir-kritis',2,2,'Mengomunikasikan Temuan dan Rekomendasi','Rekomendasi yang baik menghubungkan bukti, batasan, opsi, risiko dan cara menguji tindakan berikutnya.','Menulis ringkasan berbasis bukti yang dapat ditinjau dan ditindaklanjuti.','Pisahkan fakta, interpretasi dan rekomendasi. Nyatakan sumber data, ketidakpastian, opsi yang dipertimbangkan, pemilik tindakan, ukuran keberhasilan dan waktu evaluasi.','Apa yang membuat rekomendasi dapat diuji, bukan hanya berupa opini?','Tulis ringkasan satu paragraf berisi temuan, batasan, tindakan kecil, metrik dan waktu evaluasi.','ONET-SKILLS,OECD-LEARNING-COMPASS'),
('pembelajaran-mandiri-metakognisi',1,1,'Tujuan Belajar yang Terukur','Tujuan belajar yang baik menyatakan kemampuan yang akan ditunjukkan, konteks dan kriteria keberhasilan.','Menulis tujuan belajar yang dapat diamati dan dievaluasi.','Gunakan kata kerja yang dapat diamati seperti membandingkan, menjelaskan, merancang atau menguji. Tetapkan bukti keberhasilan dan batas waktu realistis. Pecah tujuan besar menjadi langkah kecil.','Bagaimana Anda membuktikan bahwa Anda telah menguasai keterampilan tertentu?','Tuliskan satu tujuan SMART dan bukti yang akan menunjukkan keberhasilannya.','OECD-LEARNING-COMPASS,CURRICULUM-ID-KEMENDIKDASMEN'),
('pembelajaran-mandiri-metakognisi',1,2,'Merancang Jalur Belajar Bertahap','Jalur belajar yang efektif mengurutkan prasyarat, konsep, latihan dan penerapan sesuai tujuan.','Menyusun rencana belajar dengan prasyarat, waktu dan latihan.','Mulai dari diagnosis kebutuhan, identifikasi prasyarat, pilih materi tepercaya, jadwalkan sesi, dan sisipkan latihan. Rencanakan waktu untuk mengingat kembali tanpa melihat catatan dan menerapkan konsep pada konteks baru.','Mengapa mempelajari prasyarat sebelum materi lanjutan dapat membantu?','Buat jalur belajar dua minggu dengan tiga capaian, latihan dan checkpoint.','OECD-LEARNING-COMPASS,CURRICULUM-ID-PUSKUR'),
('pembelajaran-mandiri-metakognisi',2,1,'Latihan Mengingat Kembali dan Umpan Balik','Mengingat kembali tanpa melihat jawaban dan menerima umpan balik membantu menemukan kesenjangan pemahaman.','Memilih latihan retrieval dan memperbaiki kesalahan berdasarkan bukti.','Tutup catatan lalu jelaskan ide utama, jawab soal, atau praktikkan prosedur. Setelah itu bandingkan dengan sumber tepercaya, kategorikan kesalahan, dan ulangi latihan setelah jeda. Hindari menganggap membaca berulang sama dengan penguasaan.','Bagaimana latihan mengingat kembali berbeda dari membaca ulang?','Buat lima pertanyaan dari pelajaran lalu jawab tanpa catatan dan koreksi berdasarkan rubrik.','OECD-LEARNING-COMPASS,CURRICULUM-ID-PUSKUR'),
('pembelajaran-mandiri-metakognisi',2,2,'Refleksi dan Perbaikan Strategi','Refleksi metakognitif mengidentifikasi strategi yang efektif, bukti kemajuan dan langkah perbaikan.','Menganalisis proses belajar tanpa memberi label kepribadian pada diri sendiri.','Catat tujuan, strategi, hasil, kesalahan dan rencana berikutnya. Fokus pada perilaku yang bisa diubah, misalnya frekuensi latihan atau kualitas catatan, bukan label tetap seperti “tidak berbakat”.','Apa satu perubahan strategi yang dapat diuji pada sesi belajar berikutnya?','Isi catatan refleksi: target, bukti, hambatan, strategi yang dicoba, dan eksperimen berikutnya.','OECD-LEARNING-COMPASS'),
('keterampilan-kerja-komunikasi-karier',1,1,'Komunikasi Profesional Berbasis Audiens','Komunikasi kerja efektif menyesuaikan pesan dengan tujuan, audiens, bukti dan tindakan berikutnya.','Menyusun pesan yang jelas dan dapat ditindaklanjuti.','Gunakan struktur konteks, inti pesan, detail penting, permintaan atau keputusan, dan tenggat. Bedakan fakta dari asumsi dan pilih kanal sesuai urgensi serta kebutuhan dokumentasi.','Informasi apa yang harus ada agar permintaan kerja tidak ambigu?','Tulis ulang pesan proyek yang terlalu umum menjadi permintaan dengan pemilik dan tenggat yang jelas.','ONET-SKILLS,ESCO-API'),
('keterampilan-kerja-komunikasi-karier',1,2,'Mendengar Aktif dan Umpan Balik','Mendengar aktif menguji pemahaman; umpan balik efektif menyebut perilaku teramati, dampak dan langkah berikutnya.','Memparafrasekan, mengklarifikasi dan memberi umpan balik spesifik.','Parafrasekan inti, ajukan pertanyaan klarifikasi dan rangkum kesepakatan. Saat memberi umpan balik, sebut situasi, perilaku teramati, dampak dan permintaan yang realistis; beri ruang untuk respons.','Mengapa label seperti “malas” kurang berguna dibandingkan contoh perilaku?','Buat skrip umpan balik berbasis satu observasi yang spesifik dan dapat diverifikasi.','ONET-SKILLS,ESCO-API'),
('keterampilan-kerja-komunikasi-karier',2,1,'Pemecahan Masalah dan Kolaborasi','Pemecahan masalah terstruktur memisahkan gejala, penyebab yang mungkin, opsi dan bukti untuk mengevaluasi hasil.','Membandingkan solusi dan menyepakati eksperimen kecil bersama tim.','Definisikan masalah, kumpulkan bukti, petakan penyebab alternatif, hasilkan opsi, nilai risiko dan pilih uji kecil. Tentukan tanggung jawab, tenggat, ukuran keberhasilan dan cara berbagi hasil.','Mengapa tim perlu menyepakati definisi masalah sebelum memilih solusi?','Buat matriks dua opsi solusi dengan manfaat, risiko, biaya dan metrik uji.','ONET-SKILLS,ESCO-API'),
('keterampilan-kerja-komunikasi-karier',2,2,'Pemetaan Keterampilan dan Rencana Karier','Rencana karier yang berguna menghubungkan target peran, bukti kemampuan, kesenjangan keterampilan dan pengalaman berikutnya.','Membuat peta keterampilan yang berbasis bukti dan rencana pengembangan.','Gunakan deskripsi pekerjaan dan kerangka keterampilan sebagai referensi, bukan sebagai penilaian otomatis. Catat contoh kerja atau proyek sebagai bukti, identifikasi kesenjangan, lalu rencanakan latihan dan umpan balik mentor. Sesuaikan taksonomi internasional dengan pasar kerja lokal.','Apa perbedaan antara menyatakan punya keterampilan dan menunjukkan bukti keterampilan?','Pilih satu target peran dan buat tabel keterampilan yang dibutuhkan, bukti yang tersedia, kesenjangan dan langkah 30 hari.','ONET-SKILLS,ESCO-API')
) AS v(course_slug,module_position,lesson_position,title,summary,objective,body,check_question,exercise,source_ids)
JOIN public.courses c ON c.slug=v.course_slug
JOIN public.modules m ON m.course_id=c.id AND m.position=v.module_position
ON CONFLICT (module_id,position) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content;

COMMIT;
